config:
server {
	server_name example.test;

	location / {
		add_header X-Frame-Options DENY;

		if ($http_origin ~ ^https://.*example.test) {
			add_header Access-Control-Allow-Origin $http_origin;
		}
	}
}

server {
	server_name example.test;

	location ~ /redirect {
		return 302 https://example.test$uri;
	}
}

server {
	server_name example.test;

	location / {

		if ($http_origin ~ ^https://.*example.test) {
			add_header Access-Control-Allow-Origin $http_origin;
		}
	}
}
